export interface Page<T> {
  items: T[];
  page: number;
  perPage: number;
  totalItems: number;
  totalPages: number;
  hasPrev: boolean;
  hasNext: boolean;
}

const MIN_PER_PAGE = 1;
const MIN_PAGE = 1;

/**
 * Splits `items` into pages for a list view.
 *
 * - `perPage` must be an integer of 1 or more. Anything else throws a
 *   RangeError.
 * - `totalPages` is the number of pages needed to show every item. An
 *   empty list still has 1 (empty) page.
 * - `page` is 1-based. It is rounded down to an integer first. NaN, or
 *   anything below 1, means page 1. Anything past the last page means
 *   the last page. The returned `page` is the page actually shown.
 * - `items` holds that page's items, in order. The input array is
 *   never modified.
 * - `hasPrev` is true when there is a page before this one, and
 *   `hasNext` is true when there is a page after it.
 */
export function paginate<T>(
  items: T[],
  page: number,
  perPage = 10,
): Page<T> {
  // Contract: perPage must be a positive integer.
  if (!Number.isInteger(perPage) || perPage < MIN_PER_PAGE) {
    throw new RangeError(
      `perPage must be an integer >= ${MIN_PER_PAGE}, got ${perPage}`,
    );
  }

  const totalItems = items.length;

  // An empty list still needs one (empty) page.
  const totalPages = Math.max(1, Math.ceil(totalItems / perPage));

  // Round down first, then normalise NaN / out-of-range values.
  let current = Math.floor(page);

  // NaN comparisons are always false, so guard explicitly.
  if (Number.isNaN(current)) {
    current = MIN_PAGE;
  }

  if (current < MIN_PAGE) {
    current = MIN_PAGE;
  }

  if (current > totalPages) {
    current = totalPages;
  }

  const start = (current - 1) * perPage;

  // slice, not splice — the caller's array must not be mutated.
  const pageItems = items.slice(start, start + perPage);

  return {
    items: pageItems,
    page: current,
    perPage,
    totalItems,
    totalPages,
    hasPrev: current > MIN_PAGE,
    hasNext: current < totalPages,
  };
}
```

**What was wrong and what changed**

| Bug | Root cause | Fix |
|---|---|---|
| 20 items / 10 per page → 3 pages | `Math.floor(n/per) + 1` always overshoots when `n` is a multiple of `per` | `Math.ceil(totalItems / perPage)` (floored at 1 for the empty-list case) |
| 11 items, page 1 has no Next | `start + perPage < totalItems - 1` is off-by-one (`10 < 10` is false) | `hasNext: current < totalPages` — purely positional, no arithmetic on item counts |
| Input array shrinks after a view | `items.splice(start, perPage)` **mutates** the caller's array | `items.slice(start, start + perPage)` is non-mutating |
| `?page=abc` → blank list | `NaN` fails both `< 1` and `> totalPages` guards, so `start` stays `NaN` and `slice` returns `[]` | Explicit `Number.isNaN` guard after the `Math.floor` step, before the `< 1` guard |
| No `perPage` validation | The contract requires a `RangeError` for non-integer / sub-1 values | Added the guard at the top of the function |

